package com.powercms.cms.delivery.navigation;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.security.Principal;import java.util.*;
@RestController @RequestMapping("/api/v1/sites/{siteId}/url-rewrites") public class UrlRewriteController {private final UrlRewriteService service;UrlRewriteController(UrlRewriteService s){service=s;}public record Save(@NotBlank String name,@NotBlank String pattern,@NotBlank String replacement,int priority,String status,Long lockVersion){}public record Validate(UUID id,@NotBlank String name,@NotBlank String pattern,@NotBlank String replacement,int priority){}public record Test(@NotBlank String input){}
 @PreAuthorize("@siteAuthorization.check(authentication,#siteId,'read')") @GetMapping List<UrlRewriteService.Info> list(@PathVariable UUID siteId){return service.list(siteId);}
 @PreAuthorize("@siteAuthorization.check(authentication,#siteId,'site-admin')") @PostMapping("/validate") UrlRewriteService.Validation validate(@PathVariable UUID siteId,@Valid @RequestBody Validate r){return service.validate(siteId,r.id(),r.name(),r.pattern(),r.replacement(),r.priority());}
 @PreAuthorize("@siteAuthorization.check(authentication,#siteId,'read')") @PostMapping("/test") UrlRewriteService.TestResult test(@PathVariable UUID siteId,@Valid @RequestBody Test r){return service.test(siteId,r.input(),true);}
 @PreAuthorize("@siteAuthorization.check(authentication,#siteId,'site-admin')") @PostMapping ResponseEntity<UrlRewriteService.Info> create(@PathVariable UUID siteId,@Valid @RequestBody Save r,Principal p){return ResponseEntity.status(201).body(service.save(siteId,null,r.name(),r.pattern(),r.replacement(),r.priority(),r.status(),null,p.getName()));}
 @PreAuthorize("@siteAuthorization.check(authentication,#siteId,'site-admin')") @PutMapping("/{id}") UrlRewriteService.Info update(@PathVariable UUID siteId,@PathVariable UUID id,@Valid @RequestBody Save r,Principal p){return service.save(siteId,id,r.name(),r.pattern(),r.replacement(),r.priority(),r.status(),r.lockVersion(),p.getName());}
 @PreAuthorize("@siteAuthorization.check(authentication,#siteId,'site-admin')") @DeleteMapping("/{id}") ResponseEntity<Void> delete(@PathVariable UUID siteId,@PathVariable UUID id,Principal p){service.delete(siteId,id,p.getName());return ResponseEntity.noContent().build();}}
